                    owner: ownerAddress,
                    withdrawalPeriod: withdrawalPeriod.toNumber(),
                    withdrawalCheckpointStart : withdrawalCheckpointStart.toNumber(),
                    time: time.toNumber(),
                    pwdStatus: pwdStatus,
